import android.graphics.Bitmap;import android.graphics.Matrix;import android.os.*;import android.view.*;import android.window.InputTransferToken;import maclauncher.android.framework.*;import java.nio.file.*;
/** Original input algorithms and publisher native storage; no window or injected desktop input. */
public final class NativeInputProbe {
 static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
 public static void main(String[] args)throws Exception{
  Path runtime=Path.of(args[0]),data=Path.of(args[1]);Files.createDirectories(data.resolve("files"));Files.createDirectories(data.resolve("cache"));HostFilesystem.configure(runtime,data,data.resolve("files"),data.resolve("cache"),"owned.input");
  System.setProperty("klepton.graphics",runtime.resolve("native/libklepton-graphics.dylib").toString());System.load(runtime.resolve("native/libklepton-jvm.dylib").toString());System.load(runtime.resolve("native/libnativebinding.dylib").toString());if(System.getenv("KL_ANDROID_ID_DIRECTORY")!=null)HostProcessIdentity.initializeIds();JvmNativeMemory.configure(runtime.resolve("native/libandroid_runtime.dylib"));JvmNativeMemory.initialize();if(args.length>2)System.load(args[2]);
  // ART configures resources before registering the same shared input devices.
  FrameworkResources.configure(runtime.resolve("android-framework.jar"),java.util.List.of(runtime.resolve("android-framework.jar")));
  HostInputManager.install();HostInput.initialize();
  InputDevice keyboardDevice=InputDevice.getDevice(KeyCharacterMap.VIRTUAL_KEYBOARD);
  check(keyboardDevice!=null&&keyboardDevice.isEnabled()&&keyboardDevice.supportsSource(InputDevice.SOURCE_KEYBOARD)&&keyboardDevice.getKeyboardType()==InputDevice.KEYBOARD_TYPE_ALPHABETIC,"Original input device publishes the enabled SDL alphabetic keyboard");
  var resources=android.app.ResourcesManager.getInstance().getResources(null,runtime.resolve("android-framework.jar").toString(),null,null,null,null,null,null,android.content.res.CompatibilityInfo.DEFAULT_COMPATIBILITY_INFO,NativeInputProbe.class.getClassLoader(),null);
  var configuration=resources.getConfiguration();
  check(configuration.keyboard==android.content.res.Configuration.KEYBOARD_QWERTY&&configuration.keyboardHidden==android.content.res.Configuration.KEYBOARDHIDDEN_NO&&configuration.hardKeyboardHidden==android.content.res.Configuration.HARDKEYBOARDHIDDEN_NO,"Original application resource Configuration must expose the registered SDL keyboard: "+configuration);
  MotionEvent down=HostInput.motion(0,12,25);long when=down.getDownTime();check(down.getSource()==InputDevice.SOURCE_TOUCHSCREEN&&down.getPointerCount()==1&&down.getX()==12&&down.getToolType(0)==MotionEvent.TOOL_TYPE_FINGER&&down.getPressure()==1,"SDL finger pointer native state");
  InputDevice pointer=down.getDevice();check(pointer!=null&&!pointer.isVirtual()&&pointer.getKeyboardType()==InputDevice.KEYBOARD_TYPE_NONE,"native pointer is discoverable independently of the virtual keyboard");check(pointer.getMotionRange(MotionEvent.AXIS_X,InputDevice.SOURCE_TOUCHSCREEN).getMax()>12&&pointer.getMotionRange(MotionEvent.AXIS_Y,InputDevice.SOURCE_TOUCHSCREEN).getMax()>25,"pointer reports its actual coordinate extent");down.recycle();
  MotionEvent move=HostInput.motion(2,14,30);check(move.getDownTime()==when,"gesture down time");move.addBatch(move.getEventTime()+1,17,33,1,1,0);check(move.getHistorySize()==1&&move.getHistoricalX(0)==14,"original native event history");
  Matrix matrix=new Matrix();matrix.setScale(2,3);move.transform(matrix);check(move.getX()==34&&move.getY()==99&&move.getHistoricalX(0)==28,"native matrix transformation");
  byte[] eventData;Parcel parcel=Parcel.obtain();try{move.writeToParcel(parcel,0);eventData=parcel.marshall();move.setLocation(500,500);}finally{parcel.recycle();move.recycle();}
  Parcel received=Parcel.obtain();try{received.unmarshall(eventData,0,eventData.length);received.setDataPosition(0);MotionEvent copy=MotionEvent.CREATOR.createFromParcel(received);check(copy.getX()==34&&copy.getY()==99&&copy.getHistorySize()==1&&copy.getHistoricalX(0)==28&&copy.getDownTime()==when,"native parcel bytes preserve independent history after sender recycle");copy.recycle();}finally{received.recycle();}
  MotionEvent up=HostInput.motion(MotionEvent.ACTION_UP,17,33);check(up.getToolType(0)==MotionEvent.TOOL_TYPE_FINGER&&up.getPressure()==0&&up.getDownTime()==when,"finger release preserves gesture identity");up.recycle();
  MotionEvent relative=HostInput.relative(MotionEvent.ACTION_MOVE,3,-4,MotionEvent.BUTTON_PRIMARY);check(relative.getSource()==InputDevice.SOURCE_MOUSE_RELATIVE&&relative.getToolType(0)==MotionEvent.TOOL_TYPE_MOUSE&&relative.getButtonState()==1&&relative.getY()==-4,"relative pointer native state");relative.recycle();
  KeyEvent key=HostInput.key(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_A,'a',KeyEvent.META_SHIFT_ON);check(key.getUnicodeChar()=='A'&&key.getKeyCode()==KeyEvent.KEYCODE_A&&key.getSource()==InputDevice.SOURCE_KEYBOARD,"publisher keyboard map and raw key semantics");check(KeyEvent.keyCodeFromString(KeyEvent.keyCodeToString(KeyEvent.KEYCODE_BUTTON_16))==KeyEvent.KEYCODE_BUTTON_16&&KeyEvent.isGamepadButton(KeyEvent.KEYCODE_BUTTON_16),"full key label and code surface");key.recycle();
  KeyCharacterMap keyboard=KeyCharacterMap.load(KeyCharacterMap.VIRTUAL_KEYBOARD);byte[] keyData;Parcel keys=Parcel.obtain();try{keyboard.writeToParcel(keys,0);keyData=keys.marshall();check(keyData.length>0,"original keyboard serialization writes native map data");}finally{keys.recycle();}
  Parcel receivedKeys=Parcel.obtain();try{receivedKeys.unmarshall(keyData,0,keyData.length);receivedKeys.setDataPosition(0);KeyCharacterMap copied=KeyCharacterMap.CREATOR.createFromParcel(receivedKeys);check(copied!=keyboard&&copied.equals(keyboard)&&copied.get(KeyEvent.KEYCODE_A,KeyEvent.META_SHIFT_ON)=='A'&&copied.getKeyboardType()==keyboard.getKeyboardType(),"independent publisher keyboard-map parcel byte roundtrip");}finally{receivedKeys.recycle();}
  Bitmap bitmap=Bitmap.createBitmap(new int[]{0xffff0000,0xff0000ff},2,1,Bitmap.Config.ARGB_8888);PointerIcon icon=PointerIcon.create(bitmap,1,0);int[] cursor=HostInput.cursor(icon);check(cursor[0]==2&&cursor[2]==1&&cursor[4]==0xffff0000&&cursor[5]==0xff0000ff,"raw pointer icon native raster");bitmap.recycle();
  InputTransferToken original=new InputTransferToken();Parcel token=Parcel.obtain();try{original.writeToParcel(token,0);token.setDataPosition(0);InputTransferToken copied=InputTransferToken.CREATOR.createFromParcel(token);check(original.equals(copied)&&original.hashCode()==copied.hashCode()&&original.getToken()==copied.getToken(),"local input capability identity and native lifetime");check(!original.equals(new InputTransferToken()),"distinct capability identity");}finally{token.recycle();}
  System.out.println("PASS raw input native motion/history/transform/parcel, keyboard mapping, pointer bitmap and local transfer-token ownership");
 }
}
